package com.nequard.incidents;
import com.nequard.auth.OrganizationAccessService;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1/incidents") public class IncidentController{private final IncidentRepository repo;private final OrganizationAccessService access;public IncidentController(IncidentRepository r,OrganizationAccessService a){repo=r;access=a;}@GetMapping public List<Incident> all(Authentication a){UUID org=access.currentOrganization(a);return access.isSuperAdmin(a)&&org==null?repo.findAll():repo.findByOrganizationId(org);}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','NETWORK_ENGINEER','NOC_OPERATOR')") public ResponseEntity<?> create(Authentication a,@RequestBody Incident i){try{i.setOrganizationId(access.requireOrganization(a,i.getOrganizationId()));return ResponseEntity.status(201).body(repo.save(i));}catch(Exception e){return ResponseEntity.status(403).body(Map.of("error",e.getMessage()));}}@PatchMapping("/{id}/status") public ResponseEntity<?> status(Authentication a,@PathVariable UUID id,@RequestParam String value){return repo.findById(id).filter(x->access.canAccess(a,x.getOrganizationId())).map(i->{i.setStatus(value.toUpperCase());if("RESOLVED".equalsIgnoreCase(value))i.setResolvedAt(Instant.now());return ResponseEntity.ok(repo.save(i));}).orElse(ResponseEntity.notFound().build());}}